        "// Use container, state, and updateState\nconst label = document.createElement('label');\nlabel.textContent = 'Button Text:';\nlabel.style.display = 'block';\nlabel.style.marginBottom = '5px';\nlabel.style.fontWeight = 'bold';\n\nconst input = document.createElement('input');\ninput.type = 'text';\ninput.value = state.buttonText || '';\ninput.style.width = '100%';\ninput.style.padding = '8px';\ninput.style.boxSizing = 'border-box';\ninput.addEventListener('input', () => updateState({ buttonText: input.value }));\n\ncontainer.appendChild(label);\ncontainer.appendChild(input);",
      renderView:
        "import confetti from \"https://esm.sh/canvas-confetti@1.6.0\"\n\nconst btn = document.createElement('button');\nbtn.textContent = '{{buttonText}}';\nbtn.style.padding = '20px 20px';\nbtn.style.fontSize = '30px';\nbtn.style.borderRadius = '8px';\nbtn.style.border = 'none';\nbtn.style.cursor = 'pointer';\nbtn.style.background = '#E8A33D';\nbtn.style.color = '#1C1B22';\nbtn.style.width = '100%';\nbtn.style.boxSizing = 'border-box';\n\nbtn.addEventListener('click', (event) => {\n  const rect = btn.getBoundingClientRect();\n  confetti({\n    particleCount: 80,\n    spread: 70,\n    origin: {\n      x: (rect.left + rect.width / 2) / window.innerWidth,\n      y: (rect.top + rect.height / 2) / window.innerHeight,\n    }\n  });\n});\n\ncontainer.appendChild(btn);",
